const entrada = $input.first().json;

const datos = JSON.parse(entrada.datos_clave);

const mensajes = datos.mensajes_pendientes ?? [];
const ids = datos.solicitudes_procesadas ?? [];

if (!entrada.solicitud_ref) {
  throw new Error("Falta solicitud_ref");
}

const duplicado = ids.includes(entrada.solicitud_ref);

if (!duplicado) {
  mensajes.push(entrada.mensaje_original.slice(0, 500));
  ids.push(entrada.solicitud_ref);
}

datos.mensajes_pendientes = mensajes;
datos.solicitudes_procesadas = ids.slice(-20);
datos.mensajes_desde_resumen = mensajes.length;

return [{
  json: {
    ...entrada,
    datos_clave: JSON.stringify(datos),
    contador_actualizado: mensajes.length,
    requiere_resumen: mensajes.length > 5,
    es_duplicado: duplicado
  }
}];

const raw = $input.first().json.text;

const resumen = JSON.parse(raw);

if (
  typeof resumen.asunto_principal !== "string" ||
  !Array.isArray(resumen.puntos_clave) ||
  !resumen.puntos_clave.every(p => typeof p === "string") ||
  typeof resumen.accion_requerida !== "string"
) {
  throw new Error("El resumen no cumple el contrato JSON");
}

return [{
  json: {
    asunto_principal: resumen.asunto_principal,
    puntos_clave: resumen.puntos_clave,
    accion_requerida: resumen.accion_requerida
  }
}];

