const entrada = $input.first().json;

// Identidad del departamento
const area = "Operaciones";

// Validar el resultado del Worker
if (entrada.success !== true) {
  throw new Error("El Worker no confirmó un procesamiento exitoso");
}

if (typeof entrada.resultado !== "string") {
  throw new Error("El Worker no devolvió una respuesta de texto");
}

// Limpiar formato Markdown
const respuesta = entrada.resultado
  .replace(/\r\n/g, "\n")
  .replace(/\*\*(.*?)\*\*/g, "$1")
  .replace(/\\([\\*_`[\]()~>#+\-=|{}.!])/g, "$1")
  .replace(/[ \t]+$/gm, "")
  .trim();

if (!respuesta) {
  throw new Error("La respuesta del Worker está vacía");
}

// Preparar contenido común de respuesta
const textoRespuesta = `NEXORA | ${area}\n\n${respuesta}`;

// Conservar el límite de seguridad existente
if (textoRespuesta.length > 3500) {
  throw new Error(
    `Respuesta demasiado extensa: ${textoRespuesta.length} caracteres. Máximo: 3500`
  );
}

// Construir contrato de salida
return [{
  json: {
    solicitud_ref: entrada.solicitud_ref,
    texto_respuesta: textoRespuesta,
    texto_telegram: textoRespuesta,
    longitud: textoRespuesta.length,
    valido: true
  }
}];

